pub fn wU8(comptime s: []const u8) []const u8 {
        _ = @setEvalBranchQuota(1000000);
        const str = std.unicode.utf8ToUtf16LeStringLiteral(s);
        return @alignCast(std.mem.sliceAsBytes(str));
}
